-- ══════════════════════════════════════════════════════════════════════════
-- FLOWIN · BANQUES MODÈLES — restauration, boulanger, boucher, libraire
-- Généré par admin/scripts/banques-modeles.mjs depuis admin/lib/banquesModeles/ (source de vérité).
-- NE PAS RÉÉDITER À LA MAIN : modifier les fichiers TypeScript puis relancer
--   node scripts/banques-modeles.mjs sql
--
-- ⚠ FICHIER NON APPLIQUÉ. À relire puis exécuter par Romain (execute_sql = DML).
-- Aucun DDL : la table public.banques et ses colonnes (nom, pro_id, event_ids, questions, tags,
-- statut) existent déjà en production.
--
-- Idempotent ET non destructif : ON CONFLICT (id) DO NOTHING. Si un pro a déjà modifié une banque
-- modèle, le rejouer n'écrase rien.
-- Banques « communes » : pro_id = 'flowin' (comme les banques communes du Super Admin).
-- Les banques « questions personnalisées (à compléter) » ne sont PAS insérées ici : elles se copient
-- depuis l'écran « Banques de questions » vers le compte du commerçant, qui renseigne ses réponses.
-- ══════════════════════════════════════════════════════════════════════════

INSERT INTO public.banques (id, nom, pro_id, event_ids, questions, tags, statut)
VALUES ('bq-modele-resto-pizza', 'Restauration · La pizza, de la pâte au four', 'flowin', ARRAY[]::text[],
  '[{"id":"rq-pizza-01","type":"qcm","texte":"Quel ingrédient fait gonfler la pâte à pizza ?","options":["Le sel","La levure","L’huile d’olive","La tomate"],"bonne":1,"points":1,"explication":"La levure produit du gaz carbonique qui fait lever la pâte.","theme":"Pizza","difficulte":"facile"},{"id":"rq-pizza-02","type":"qcm","texte":"Quels sont les ingrédients de base d’une pâte à pizza classique ?","options":["Farine, œufs, beurre et sucre","Pommes de terre, crème et fromage","Farine, eau, sel et levure","Semoule, lait, miel et vinaigre"],"bonne":2,"points":1,"explication":"Une pâte à pizza tient en quatre ingrédients : farine, eau, sel et levure (souvent un filet d’huile d’olive).","theme":"Pizza","difficulte":"facile"},{"id":"rq-pizza-03","type":"qcm","texte":"Pourquoi laisse-t-on reposer la pâte avant de l’étaler ?","options":["Pour qu’elle sèche complètement","Pour qu’elle refroidisse avant la cuisson","Pour lui retirer sa levure","Pour qu’elle lève et devienne souple"],"bonne":3,"points":1,"explication":"Pendant le repos, la levure travaille et la pâte se détend : elle est plus facile à étaler.","theme":"Pizza","difficulte":"facile"},{"id":"rq-pizza-04","type":"qcm","texte":"De quelle ville italienne la pizza est-elle originaire ?","options":["Milan","Naples","Venise","Turin"],"bonne":1,"points":1,"explication":"La pizza est née à Naples, où elle est devenue un plat emblématique.","theme":"Pizza","difficulte":"facile"},{"id":"rq-pizza-05","type":"qcm","texte":"Quelle pizza reprend, dit-on, les trois couleurs du drapeau italien ?","options":["La Reine","La Calzone","La Margherita","La Quatre fromages"],"bonne":2,"points":1,"explication":"Tomate rouge, mozzarella blanche, basilic vert : la Margherita rappelle les couleurs de l’Italie.","theme":"Pizza","difficulte":"facile"},{"id":"rq-pizza-06","type":"qcm","texte":"À quelle température peut monter un four à bois de pizzeria napolitaine ?","options":["Environ 100 °C","Environ 150 °C","Environ 200 °C","Plus de 400 °C"],"bonne":3,"points":1,"explication":"Les fours à bois traditionnels montent en général entre 400 et 500 °C, bien plus qu’un four de maison.","theme":"Pizza","difficulte":"moyen"},{"id":"rq-pizza-07","type":"qcm","texte":"Combien de temps cuit une pizza dans un four à bois très chaud ?","options":["Environ 90 secondes","Environ 10 minutes","Environ 25 minutes","Environ 45 minutes"],"bonne":0,"points":1,"explication":"À cette chaleur, une pizza cuit en une à deux minutes seulement.","theme":"Pizza","difficulte":"moyen"},{"id":"rq-pizza-08","type":"qcm","texte":"Pourquoi fait-on longuement préchauffer le four avant d’enfourner une pizza ?","options":["Pour que la pizza reste crue au centre","Pour faire refroidir la sauce","Pour que la pâte cuise vite et devienne croustillante","Pour dessaler la pâte"],"bonne":2,"points":1,"explication":"Un four bien chaud saisit la pâte : le dessous croustille avant que la garniture ne sèche.","theme":"Pizza","difficulte":"moyen"},{"id":"rq-pizza-09","type":"qcm","texte":"Que veut dire « calzone » en cuisine ?","options":["Une pizza sans fromage","Une pizza à la crème","Une pizza servie froide","Une pizza repliée sur elle-même"],"bonne":3,"points":1,"explication":"La calzone est une pizza garnie puis repliée en demi-lune avant la cuisson.","theme":"Pizza","difficulte":"moyen"},{"id":"rq-pizza-10","type":"qcm","texte":"Pourquoi certains pizzaïolos laissent-ils la pâte reposer 24 heures ou plus au frais ?","options":["Pour lui donner plus de goût et de souplesse","Pour la faire sécher","Pour lui faire perdre son sel","Parce que le four n’est pas prêt"],"bonne":0,"points":1,"explication":"Une longue levée lente au frais développe les arômes et rend la pâte plus souple.","theme":"Pizza","difficulte":"moyen"},{"id":"rq-pizza-11","type":"qcm","texte":"Que désigne le « 00 » sur un sac de farine italienne ?","options":["Le nombre de grammes de sel","Une mouture très fine","L’année de la récolte","Le taux d’humidité"],"bonne":1,"points":1,"explication":"Le « 00 » indique le degré de finesse de la mouture : c’est la plus fine.","theme":"Pizza","difficulte":"moyen"},{"id":"rq-pizza-12","type":"qcm","texte":"Quelle garniture porte la pizza « marinara » traditionnelle ?","options":["Tomate, mozzarella et basilic","Jambon et champignons","Chèvre, miel et noix","Tomate, ail, origan et huile d’olive"],"bonne":3,"points":1,"explication":"La marinara est la pizza sans fromage : tomate, ail, origan et un filet d’huile d’olive.","theme":"Pizza","difficulte":"difficile"}]'::jsonb,
  ARRAY['quiz','restaurateur','pizzeria','modele']::text[], 'valide')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.banques (id, nom, pro_id, event_ids, questions, tags, statut)
VALUES ('bq-modele-resto-cuissons', 'Restauration · Temps de cuisson', 'flowin', ARRAY[]::text[],
  '[{"id":"rq-cuisson-01","type":"qcm","texte":"Combien de temps cuit un œuf à la coque dans l’eau bouillante ?","options":["Environ 30 secondes","Environ 3 minutes","Environ 12 minutes","Environ 25 minutes"],"bonne":1,"points":1,"explication":"Trois minutes environ : le blanc est pris et le jaune reste liquide.","theme":"Temps de cuisson","difficulte":"facile"},{"id":"rq-cuisson-02","type":"qcm","texte":"Combien de temps cuit un œuf dur dans l’eau bouillante ?","options":["Environ 1 minute","Environ 3 minutes","Environ 10 minutes","Environ 25 minutes"],"bonne":2,"points":1,"explication":"Compter une dizaine de minutes pour un blanc et un jaune bien fermes.","theme":"Temps de cuisson","difficulte":"facile"},{"id":"rq-cuisson-03","type":"qcm","texte":"Combien de temps cuit un œuf mollet dans l’eau bouillante ?","options":["Environ 1 minute","Environ 15 minutes","Environ 20 minutes","Environ 6 minutes"],"bonne":3,"points":1,"explication":"Six minutes environ : le blanc est ferme, le jaune encore coulant.","theme":"Temps de cuisson","difficulte":"moyen"},{"id":"rq-cuisson-04","type":"qcm","texte":"Que veut dire « al dente » pour des pâtes ?","options":["Cuites très longtemps jusqu’à devenir molles","Cuites mais encore fermes sous la dent","Servies froides","Cuites sans eau"],"bonne":1,"points":1,"explication":"Des pâtes « al dente » gardent une petite résistance en bouche.","theme":"Temps de cuisson","difficulte":"facile"},{"id":"rq-cuisson-05","type":"qcm","texte":"Quelle quantité de sel met-on environ dans l’eau de cuisson des pâtes ?","options":["Environ 1 g par litre","Environ 50 g par litre","Environ 10 g par litre","Environ 100 g par litre"],"bonne":2,"points":1,"explication":"Une dizaine de grammes par litre assaisonne les pâtes sans les rendre trop salées.","theme":"Temps de cuisson","difficulte":"moyen"},{"id":"rq-cuisson-06","type":"qcm","texte":"Les pâtes fraîches cuisent en général…","options":["Bien plus lentement que les pâtes sèches","Exactement au même rythme","Pendant une heure","Bien plus vite que les pâtes sèches"],"bonne":3,"points":1,"explication":"Les pâtes fraîches contiennent déjà de l’eau : quelques minutes suffisent.","theme":"Temps de cuisson","difficulte":"facile"},{"id":"rq-cuisson-07","type":"qcm","texte":"Combien de temps cuit environ du riz blanc à grains longs dans l’eau bouillante ?","options":["Environ 10 à 12 minutes","Environ 2 minutes","Environ 45 minutes","Environ 1 h 30"],"bonne":0,"points":1,"explication":"Le temps exact est indiqué sur le paquet, autour de dix à douze minutes.","theme":"Temps de cuisson","difficulte":"moyen"},{"id":"rq-cuisson-08","type":"qcm","texte":"Quelle cuisson de viande rouge est la moins cuite ?","options":["À point","Saignante","Bleue","Bien cuite"],"bonne":2,"points":1,"explication":"Dans l’ordre : bleue, saignante, à point, bien cuite.","theme":"Temps de cuisson","difficulte":"facile"},{"id":"rq-cuisson-09","type":"qcm","texte":"Comment cuit-on des noix de Saint-Jacques à la poêle ?","options":["Pendant 20 minutes par face","Pendant 40 minutes à feu doux","Une heure au four","Très vite, environ 1 à 2 minutes par face"],"bonne":3,"points":1,"explication":"Une cuisson courte garde leur chair fondante ; trop longtemps, elles durcissent.","theme":"Temps de cuisson","difficulte":"moyen"},{"id":"rq-cuisson-10","type":"qcm","texte":"Pourquoi cuit-on souvent les frites en deux fois ?","options":["Pour qu’elles soient dorées dehors et moelleuses dedans","Pour qu’elles absorbent plus de sel","Pour qu’elles restent blanches","Parce que la première friture les rend crues"],"bonne":0,"points":1,"explication":"Une première cuisson plus douce cuit l’intérieur, la seconde, plus chaude, dore l’extérieur.","theme":"Temps de cuisson","difficulte":"moyen"},{"id":"rq-cuisson-11","type":"qcm","texte":"Quel temps de cuisson est généralement conseillé pour un filet de poisson fin à la poêle ?","options":["Une heure par face","Quelques minutes par face","Plus de deux heures","Aucun : il se mange toujours cru"],"bonne":1,"points":1,"explication":"Un poisson fin cuit vite ; le temps dépend surtout de l’épaisseur du filet.","theme":"Temps de cuisson","difficulte":"difficile"}]'::jsonb,
  ARRAY['quiz','restaurateur','pizzeria','modele']::text[], 'valide')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.banques (id, nom, pro_id, event_ids, questions, tags, statut)
VALUES ('bq-modele-resto-origines', 'Restauration · D’où viennent nos aliments ?', 'flowin', ARRAY[]::text[],
  '[{"id":"rq-origine-01","type":"qcm","texte":"Sur quel continent la tomate a-t-elle été cultivée en premier ?","options":["En Europe","En Amérique","En Asie","En Afrique"],"bonne":1,"points":1,"explication":"La tomate vient d’Amérique et est arrivée en Europe au XVIe siècle.","theme":"Origines","difficulte":"facile"},{"id":"rq-origine-02","type":"qcm","texte":"Dans quelle région du monde la pomme de terre a-t-elle été cultivée en premier ?","options":["Les Alpes","L’Himalaya","Les Andes","Les Pyrénées"],"bonne":2,"points":1,"explication":"La pomme de terre est originaire des Andes, en Amérique du Sud.","theme":"Origines","difficulte":"moyen"},{"id":"rq-origine-03","type":"qcm","texte":"Sur quel continent le riz a-t-il été cultivé en premier ?","options":["En Amérique du Nord","En Europe","En Océanie","En Asie"],"bonne":3,"points":1,"explication":"Le riz est cultivé en Asie depuis des millénaires.","theme":"Origines","difficulte":"facile"},{"id":"rq-origine-04","type":"qcm","texte":"D’où vient le cacao, base du chocolat ?","options":["De Scandinavie","D’Amérique centrale et du Sud","Des Alpes","D’Australie"],"bonne":1,"points":1,"explication":"Le cacaoyer est originaire des régions chaudes et humides d’Amérique.","theme":"Origines","difficulte":"facile"},{"id":"rq-origine-05","type":"qcm","texte":"De quelle région du monde le caféier est-il originaire ?","options":["De Scandinavie","D’Amérique du Nord","D’Afrique de l’Est (Éthiopie)","D’Australie"],"bonne":2,"points":1,"explication":"Le caféier est originaire d’Éthiopie avant d’être cultivé dans de nombreux pays.","theme":"Origines","difficulte":"moyen"},{"id":"rq-origine-06","type":"qcm","texte":"Dans quel pays le Parmigiano Reggiano est-il fabriqué ?","options":["En Espagne","Au Portugal","En Grèce","En Italie"],"bonne":3,"points":1,"explication":"Ce fromage à pâte dure vient d’Émilie-Romagne, en Italie, et porte une appellation d’origine protégée.","theme":"Origines","difficulte":"facile"},{"id":"rq-origine-07","type":"qcm","texte":"De quelle région de France vient le camembert ?","options":["La Normandie","La Bretagne","L’Alsace","La Provence"],"bonne":0,"points":1,"explication":"Le camembert de Normandie est une appellation d’origine protégée.","theme":"Origines","difficulte":"facile"},{"id":"rq-origine-08","type":"qcm","texte":"Avec quel lait le roquefort est-il fabriqué ?","options":["Du lait de vache","Du lait de chèvre","Du lait de brebis","Du lait de jument"],"bonne":2,"points":1,"explication":"Le roquefort est un fromage au lait de brebis, affiné dans des caves.","theme":"Origines","difficulte":"moyen"},{"id":"rq-origine-09","type":"qcm","texte":"De quelle plante vient la vanille ?","options":["D’un palmier","D’un cactus","D’un buisson de lavande","D’une orchidée"],"bonne":3,"points":1,"explication":"La gousse de vanille est le fruit d’une orchidée.","theme":"Origines","difficulte":"moyen"},{"id":"rq-origine-10","type":"qcm","texte":"Le safran est fait à partir…","options":["Des filaments (stigmates) d’une fleur de crocus","Des graines d’un tournesol","Des feuilles d’un olivier","Des racines d’une carotte"],"bonne":0,"points":1,"explication":"Chaque fleur de crocus ne donne que quelques filaments rouges, récoltés à la main : d’où son prix.","theme":"Origines","difficulte":"moyen"}]'::jsonb,
  ARRAY['quiz','restaurateur','pizzeria','modele']::text[], 'valide')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.banques (id, nom, pro_id, event_ids, questions, tags, statut)
VALUES ('bq-modele-resto-saisons', 'Restauration · Fruits et légumes de saison', 'flowin', ARRAY[]::text[],
  '[{"id":"rq-saison-01","type":"qcm","texte":"Quel fruit rouge est de saison au printemps en France ?","options":["La clémentine","La fraise","La châtaigne","La mandarine"],"bonne":1,"points":1,"explication":"Les premières fraises de France arrivent au printemps.","theme":"Printemps","difficulte":"facile"},{"id":"rq-saison-02","type":"qcm","texte":"Quel légume « royal » est de saison au printemps ?","options":["La courge","Le chou de Bruxelles","L’asperge","La betterave"],"bonne":2,"points":1,"explication":"La saison de l’asperge s’étend du printemps au début de l’été.","theme":"Printemps","difficulte":"facile"},{"id":"rq-saison-03","type":"qcm","texte":"Le « violet de Provence » est une variété de quel légume ?","options":["De l’aubergine","De la betterave","Du chou","L’artichaut"],"bonne":3,"points":1,"explication":"Le violet de Provence est un petit artichaut très présent sur les étals du sud au printemps.","theme":"Printemps","difficulte":"moyen"},{"id":"rq-saison-04","type":"qcm","texte":"Quel légume-fruit est de pleine saison en été ?","options":["Le potiron","La tomate","Le poireau","Le navet"],"bonne":1,"points":1,"explication":"La tomate se récolte surtout de juin à septembre.","theme":"Été","difficulte":"facile"},{"id":"rq-saison-05","type":"qcm","texte":"Quel fruit est de saison en été ?","options":["La clémentine","La poire d’hiver","La pêche","La châtaigne"],"bonne":2,"points":1,"explication":"Pêches, abricots et melons sont des fruits de l’été.","theme":"Été","difficulte":"facile"},{"id":"rq-saison-06","type":"qcm","texte":"Quel légume est l’un des ingrédients de la ratatouille en été ?","options":["Le potimarron","Le panais","La mâche","La courgette"],"bonne":3,"points":1,"explication":"Courgette, aubergine, poivron et tomate : le quatuor d’été de la ratatouille.","theme":"Été","difficulte":"moyen"},{"id":"rq-saison-07","type":"qcm","texte":"Quel légume orange est un symbole de l’automne ?","options":["La courge (potiron)","La tomate","La courgette","Le radis"],"bonne":0,"points":1,"explication":"Potiron, potimarron et autres courges se récoltent à l’automne.","theme":"Automne","difficulte":"facile"},{"id":"rq-saison-08","type":"qcm","texte":"Quel fruit à coque se ramasse en automne ?","options":["La fraise","La cerise","La châtaigne","L’abricot"],"bonne":2,"points":1,"explication":"Les châtaignes tombent à l’automne, de fin septembre à novembre.","theme":"Automne","difficulte":"moyen"},{"id":"rq-saison-09","type":"qcm","texte":"Quel agrume est de saison en hiver ?","options":["La pastèque","La fraise","La pêche","La clémentine"],"bonne":3,"points":1,"explication":"Clémentines, oranges et citrons sont les agrumes de l’hiver.","theme":"Hiver","difficulte":"facile"},{"id":"rq-saison-10","type":"qcm","texte":"Quel légume blanc et croquant est un légume d’hiver ?","options":["L’endive","Le concombre","La courgette","Le poivron"],"bonne":0,"points":1,"explication":"L’endive pousse à l’abri de la lumière et se récolte surtout de l’automne au printemps.","theme":"Hiver","difficulte":"moyen"}]'::jsonb,
  ARRAY['quiz','restaurateur','pizzeria','modele']::text[], 'valide')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.banques (id, nom, pro_id, event_ids, questions, tags, statut)
VALUES ('bq-modele-resto-eveil', 'Restauration · Bien manger, bien consommer', 'flowin', ARRAY[]::text[],
  '[{"id":"rq-eveil-01","type":"qcm","texte":"Que signifie « DLC » sur un emballage ?","options":["Dosage légal en calories","Date limite de consommation","Délai de livraison courant","Date de lancement commerciale"],"bonne":1,"points":1,"explication":"Passé la DLC, le produit ne doit plus être consommé : elle figure sur les produits très périssables.","theme":"Anti-gaspi","difficulte":"facile"},{"id":"rq-eveil-02","type":"qcm","texte":"Que signifie la mention « à consommer de préférence avant » ?","options":["Le produit devient inutilisable le lendemain","Le produit doit être congelé","La qualité optimale est garantie jusqu’à cette date","Le produit est déjà périmé"],"bonne":2,"points":1,"explication":"Cette date (DDM) indique une qualité optimale ; elle ne signifie pas que le produit est périmé.","theme":"Anti-gaspi","difficulte":"moyen"},{"id":"rq-eveil-03","type":"qcm","texte":"Que signifie « premier entré, premier sorti » en cuisine ?","options":["Servir d’abord les clients arrivés les premiers","Jeter les restes de la veille","Ranger les produits au hasard","Utiliser d’abord les produits les plus anciens"],"bonne":3,"points":1,"explication":"Cette règle évite que des produits ne se perdent au fond d’une réserve.","theme":"Anti-gaspi","difficulte":"facile"},{"id":"rq-eveil-04","type":"qcm","texte":"Au restaurant, un client qui n’a pas fini son repas peut demander…","options":["Que l’on jette son plat devant lui","À emporter ses restes dans un contenant","À payer le plat deux fois","Que le chef finisse son assiette"],"bonne":1,"points":1,"explication":"En France, les restaurants doivent mettre à disposition, sur demande, un contenant pour emporter les restes (le « gourmet bag »).","theme":"Anti-gaspi","difficulte":"moyen"},{"id":"rq-eveil-05","type":"qcm","texte":"Depuis 2024, que doivent trier à la source tous les producteurs de déchets en France, restaurants compris ?","options":["Uniquement le verre","Uniquement les piles","Les biodéchets (restes alimentaires)","Rien de nouveau : le tri reste facultatif"],"bonne":2,"points":1,"explication":"Les déchets alimentaires doivent être triés pour être compostés ou transformés en énergie.","theme":"Anti-gaspi","difficulte":"moyen"},{"id":"rq-eveil-06","type":"qcm","texte":"Combien d’intermédiaires au maximum compte un « circuit court » en France ?","options":["Dix","Au moins trois","Aucun, c’est impossible","Un seul"],"bonne":3,"points":1,"explication":"En France, un circuit court compte au plus un intermédiaire entre le producteur et le consommateur.","theme":"Circuits courts","difficulte":"difficile"},{"id":"rq-eveil-07","type":"qcm","texte":"Que garantit le « Label Rouge » ?","options":["Une qualité supérieure à celle des produits courants","Un produit toujours bio","Un produit toujours fabriqué à moins de 10 km","Un produit sans aucun ingrédient animal"],"bonne":0,"points":1,"explication":"Le Label Rouge est un signe officiel de qualité supérieure, contrôlé par des organismes indépendants.","theme":"Labels","difficulte":"moyen"},{"id":"rq-eveil-08","type":"qcm","texte":"Que désigne le logo « AB » sur un produit alimentaire ?","options":["Aliment de Base","Appellation de Boisson","L’agriculture biologique","Allégé en Beurre"],"bonne":2,"points":1,"explication":"Le logo « AB » signale un produit issu de l’agriculture biologique.","theme":"Labels","difficulte":"facile"},{"id":"rq-eveil-09","type":"qcm","texte":"Que signifie le sigle AOP ?","options":["Aliment d’Origine Pasteurisée","Appellation Optionnelle de Production","Agriculture Organisée Privée","Appellation d’Origine Protégée"],"bonne":3,"points":1,"explication":"L’AOP relie un produit à un terroir précis et à un savoir-faire reconnu.","theme":"Labels","difficulte":"moyen"},{"id":"rq-eveil-10","type":"qcm","texte":"Combien d’allergènes doivent être signalés au client dans un restaurant (liste européenne) ?","options":["14","4","8","25"],"bonne":0,"points":1,"explication":"La réglementation européenne impose d’informer sur 14 allergènes : gluten, lait, œufs, arachides, poissons, etc.","theme":"Allergènes","difficulte":"moyen"},{"id":"rq-eveil-11","type":"qcm","texte":"Lequel de ces ingrédients fait partie des allergènes à déclarer ?","options":["La tomate","Le gluten (certaines céréales)","La carotte","La pomme"],"bonne":1,"points":1,"explication":"Les céréales contenant du gluten figurent sur la liste des 14 allergènes.","theme":"Allergènes","difficulte":"facile"},{"id":"rq-eveil-12","type":"qcm","texte":"Dans un restaurant qui sert des repas en France, la carafe d’eau du robinet est…","options":["Facturée au prix du vin","Interdite","Réservée aux enfants","Proposée gratuitement à la demande du client"],"bonne":3,"points":1,"explication":"Une carafe d’eau doit être donnée gratuitement sur demande : bon pour le porte-monnaie et pour la planète.","theme":"Bon à savoir","difficulte":"facile"},{"id":"rq-eveil-13","type":"qcm","texte":"À quelle température doit rester un réfrigérateur pour bien conserver les aliments frais ?","options":["Environ 4 °C","Environ 12 °C","Environ 20 °C","Environ 30 °C"],"bonne":0,"points":1,"explication":"Autour de 4 °C, le froid ralentit nettement l’altération des aliments.","theme":"Bon à savoir","difficulte":"moyen"}]'::jsonb,
  ARRAY['quiz','restaurateur','pizzeria','modele']::text[], 'valide')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.banques (id, nom, pro_id, event_ids, questions, tags, statut)
VALUES ('bq-modele-resto-region', 'Restauration · Provence, pays niçois et Vence', 'flowin', ARRAY[]::text[],
  '[{"id":"rq-region-01","type":"qcm","texte":"De quoi est faite la socca niçoise ?","options":["De farine de maïs","De farine de pois chiche","De pommes de terre","De semoule de blé"],"bonne":1,"points":1,"explication":"La socca est une galette fine de farine de pois chiche, d’eau et d’huile d’olive, cuite à four très chaud.","theme":"Spécialités","difficulte":"facile"},{"id":"rq-region-02","type":"qcm","texte":"Quelle garniture recouvre la pissaladière niçoise ?","options":["Du chèvre et du miel","Des champignons et de la crème","Des oignons confits, des anchois et des olives","Du jambon et du fromage"],"bonne":2,"points":1,"explication":"Les oignons longuement cuits sont la base de la pissaladière.","theme":"Spécialités","difficulte":"moyen"},{"id":"rq-region-03","type":"qcm","texte":"Quel plat provençal mijote aubergines, courgettes, poivrons, tomates et oignons ?","options":["Le gratin dauphinois","La choucroute","Le cassoulet","La ratatouille"],"bonne":3,"points":1,"explication":"La ratatouille est un plat de légumes d’été de la cuisine provençale et niçoise.","theme":"Spécialités","difficulte":"facile"},{"id":"rq-region-04","type":"qcm","texte":"Le mot « tapenade » vient du provençal « tapéno ». Que désigne ce mot ?","options":["Les olives","Les câpres","Les anchois","L’ail"],"bonne":1,"points":1,"explication":"La tapenade doit son nom aux câpres, même si les olives en sont l’ingrédient principal.","theme":"Spécialités","difficulte":"difficile"},{"id":"rq-region-05","type":"qcm","texte":"Quels sont les deux ingrédients de base d’un aïoli ?","options":["Le basilic et le parmesan","Le citron et le beurre","L’ail et l’huile d’olive","La tomate et l’oignon"],"bonne":2,"points":1,"explication":"L’aïoli est une émulsion d’ail et d’huile d’olive. Le pistou, lui, est à base de basilic.","theme":"Spécialités","difficulte":"facile"},{"id":"rq-region-06","type":"qcm","texte":"Que sont les « petits farcis » niçois ?","options":["De petits gâteaux fourrés","Des raviolis frits","Des petits poissons panés","De petits légumes (tomates, courgettes, oignons…) garnis de farce"],"bonne":3,"points":1,"explication":"Tomates, courgettes, oignons ou aubergines sont creusés, farcis puis cuits au four.","theme":"Spécialités","difficulte":"moyen"},{"id":"rq-region-07","type":"qcm","texte":"Quel légume-feuille garnit la tourte niçoise, salée ou sucrée ?","options":["Les blettes","Le chou","La laitue","Le poireau"],"bonne":0,"points":1,"explication":"La tourte de blettes est une spécialité niçoise, qui existe en version salée comme en version sucrée.","theme":"Spécialités","difficulte":"difficile"},{"id":"rq-region-08","type":"qcm","texte":"De quelle ville est originaire la bouillabaisse ?","options":["Lyon","Bordeaux","Marseille","Strasbourg"],"bonne":2,"points":1,"explication":"La bouillabaisse est une soupe de poissons de roche née à Marseille.","theme":"Spécialités","difficulte":"facile"},{"id":"rq-region-09","type":"qcm","texte":"Quel arbre est emblématique des collines de l’arrière-pays méditerranéen ?","options":["Le sapin","Le bouleau","Le hêtre","L’olivier"],"bonne":3,"points":1,"explication":"L’olivier pousse sur les restanques des collines autour de Nice et de Vence.","theme":"Produits locaux","difficulte":"facile"},{"id":"rq-region-10","type":"qcm","texte":"Quelle variété d’olive donne l’olive de Nice AOP ?","options":["Le cailletier","La picholine","La lucques","La tanche"],"bonne":0,"points":1,"explication":"L’olive de Nice et l’huile d’olive de Nice proviennent de la variété cailletier.","theme":"Produits locaux","difficulte":"difficile"},{"id":"rq-region-11","type":"qcm","texte":"Lequel de ces ingrédients entre dans les « herbes de Provence » ?","options":["La vanille","Le thym","La cannelle","Le gingembre"],"bonne":1,"points":1,"explication":"Thym, romarin, sarriette et origan font partie des herbes de Provence.","theme":"Produits locaux","difficulte":"moyen"},{"id":"rq-region-12","type":"qcm","texte":"Quelle appellation de vin se trouve sur les collines de Nice ?","options":["Cassis","Bandol","Palette","Bellet"],"bonne":3,"points":1,"explication":"Le vignoble de Bellet s’étend sur les collines autour de Nice.","theme":"Produits locaux","difficulte":"difficile"},{"id":"rq-region-13","type":"qcm","texte":"De quelle ville provençale le calisson est-il la spécialité ?","options":["Aix-en-Provence","Nice","Marseille","Avignon"],"bonne":0,"points":1,"explication":"Le calisson est une confiserie d’amandes et de fruits confits, glacée de sucre.","theme":"Produits locaux","difficulte":"moyen"},{"id":"rq-region-14","type":"qcm","texte":"Quelle ville de la Côte d’Azur organise chaque hiver la Fête du Citron ?","options":["Cannes","Menton","Antibes","Grasse"],"bonne":1,"points":1,"explication":"Menton est connue pour ses citrons et pour sa Fête du Citron.","theme":"Produits locaux","difficulte":"facile"},{"id":"rq-region-15","type":"qcm","texte":"Dans quel département se trouve Vence ?","options":["Le Var","Les Bouches-du-Rhône","Les Alpes-Maritimes (06)","Le Vaucluse"],"bonne":2,"points":1,"explication":"Vence est dans les Alpes-Maritimes, à quelques kilomètres de la mer.","theme":"Histoire et culture","difficulte":"facile"},{"id":"rq-region-16","type":"qcm","texte":"Quel peintre a conçu la chapelle du Rosaire de Vence ?","options":["Henri Matisse","Pablo Picasso","Auguste Renoir","Paul Cézanne"],"bonne":0,"points":1,"explication":"Henri Matisse a conçu la chapelle du Rosaire, inaugurée en 1951.","theme":"Histoire et culture","difficulte":"facile"},{"id":"rq-region-17","type":"qcm","texte":"Dans quel village près de Vence se trouve la Fondation Maeght, consacrée à l’art moderne ?","options":["Gourdon","Saint-Paul-de-Vence","Tourrettes-sur-Loup","Èze"],"bonne":1,"points":1,"explication":"La Fondation Maeght, ouverte en 1964, est l’un des grands lieux d’art moderne du sud de la France.","theme":"Histoire et culture","difficulte":"moyen"},{"id":"rq-region-18","type":"qcm","texte":"Quelle ville voisine est connue pour sa tradition de parfumerie ?","options":["Menton","Fréjus","Grasse","Hyères"],"bonne":2,"points":1,"explication":"Grasse est depuis longtemps la capitale française du parfum.","theme":"Histoire et culture","difficulte":"facile"},{"id":"rq-region-19","type":"qcm","texte":"En quelle année le comté de Nice a-t-il été rattaché à la France ?","options":["1789","1848","1914","1860"],"bonne":3,"points":1,"explication":"Le rattachement du comté de Nice à la France date de 1860.","theme":"Histoire et culture","difficulte":"moyen"},{"id":"rq-region-20","type":"qcm","texte":"Comment appelle-t-on la langue traditionnelle de Nice, proche de l’occitan ?","options":["Le breton","Le niçois (nissart)","L’alsacien","Le basque"],"bonne":1,"points":1,"explication":"Le niçois est la langue régionale traditionnelle du pays niçois.","theme":"Histoire et culture","difficulte":"moyen"},{"id":"rq-region-21","type":"qcm","texte":"Dans quelle ville se déroule le festival Nuits du Sud ?","options":["Nice","Cannes","Vence","Grasse"],"bonne":2,"points":1,"explication":"Le festival Nuits du Sud anime Vence chaque été.","theme":"Histoire et culture","difficulte":"facile"}]'::jsonb,
  ARRAY['quiz','restaurateur','pizzeria','modele']::text[], 'valide')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.banques (id, nom, pro_id, event_ids, questions, tags, statut)
VALUES ('bq-modele-resto-culture', 'Restauration · Culture gastronomique', 'flowin', ARRAY[]::text[],
  '[{"id":"rq-culture-01","type":"qcm","texte":"Que signifie « mise en place » en cuisine ?","options":["Mettre la table en terrasse","Tout préparer avant le service","Nettoyer la cuisine après le service","Choisir le menu du jour"],"bonne":1,"points":1,"explication":"La mise en place, ce sont les préparatifs qui permettent d’aller vite pendant le service.","theme":"Vocabulaire","difficulte":"facile"},{"id":"rq-culture-02","type":"qcm","texte":"Comment appelle-t-on le responsable d’une brigade de cuisine ?","options":["Le sommelier","Le plongeur","Le chef de cuisine","Le maître d’hôtel"],"bonne":2,"points":1,"explication":"Le chef de cuisine dirige l’équipe en cuisine et compose la carte.","theme":"Vocabulaire","difficulte":"facile"},{"id":"rq-culture-03","type":"qcm","texte":"Quel professionnel du restaurant conseille sur les vins ?","options":["Le pâtissier","Le plongeur","Le boucher","Le sommelier"],"bonne":3,"points":1,"explication":"Le sommelier choisit les vins de la cave et conseille les clients.","theme":"Vocabulaire","difficulte":"facile"},{"id":"rq-culture-04","type":"qcm","texte":"Que fait-on quand on « déglace » une poêle ?","options":["On la plonge dans l’eau glacée","On verse un liquide pour décoller les sucs de cuisson","On la met au congélateur","On la recouvre de papier"],"bonne":1,"points":1,"explication":"Le liquide (vin, bouillon…) décolle les sucs, très savoureux, au fond de la poêle.","theme":"Techniques","difficulte":"moyen"},{"id":"rq-culture-05","type":"qcm","texte":"Que signifie « blanchir » des légumes ?","options":["Les passer à l’eau de Javel","Les peler à vif","Les plonger brièvement dans l’eau bouillante","Les saupoudrer de farine"],"bonne":2,"points":1,"explication":"Le blanchiment, suivi d’un bain d’eau froide, fixe la couleur et le croquant des légumes.","theme":"Techniques","difficulte":"moyen"},{"id":"rq-culture-06","type":"qcm","texte":"Quel ingrédient lie l’huile dans une mayonnaise ?","options":["Le sucre","La farine","Le lait","Le jaune d’œuf"],"bonne":3,"points":1,"explication":"Le jaune d’œuf émulsionne l’huile pour donner une sauce onctueuse.","theme":"Techniques","difficulte":"moyen"},{"id":"rq-culture-07","type":"qcm","texte":"Combien de saveurs de base distingue-t-on généralement ?","options":["Cinq","Deux","Trois","Neuf"],"bonne":0,"points":1,"explication":"Sucré, salé, acide, amer et umami.","theme":"Saveurs","difficulte":"moyen"},{"id":"rq-culture-08","type":"qcm","texte":"Quel fromage crémeux entre dans la recette du tiramisu ?","options":["Le roquefort","Le comté","Le mascarpone","Le camembert"],"bonne":2,"points":1,"explication":"Le mascarpone est un fromage frais italien, base crémeuse du tiramisu.","theme":"Produits","difficulte":"facile"},{"id":"rq-culture-09","type":"qcm","texte":"Où récolte-t-on la fleur de sel ?","options":["Dans des mines profondes","Au sommet des montagnes","Dans les forêts","À la surface des marais salants"],"bonne":3,"points":1,"explication":"La fleur de sel est le fin cristal qui se forme à la surface de l’eau des marais salants.","theme":"Produits","difficulte":"moyen"},{"id":"rq-culture-10","type":"qcm","texte":"La truffe est…","options":["Un champignon qui pousse sous terre","Un fruit d’arbre","Un légume-racine","Une algue"],"bonne":0,"points":1,"explication":"La truffe est un champignon souterrain, recherché pour son parfum.","theme":"Produits","difficulte":"facile"},{"id":"rq-culture-11","type":"qcm","texte":"En quelle année « le repas gastronomique des Français » a-t-il été inscrit à l’UNESCO ?","options":["1994","2010","2002","2016"],"bonne":1,"points":1,"explication":"En 2010, le repas gastronomique des Français a été inscrit au patrimoine culturel immatériel de l’humanité.","theme":"Patrimoine","difficulte":"difficile"}]'::jsonb,
  ARRAY['quiz','restaurateur','pizzeria','modele']::text[], 'valide')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.banques (id, nom, pro_id, event_ids, questions, tags, statut)
