INSERT INTO public.banques (id, nom, pro_id, event_ids, questions, tags, statut)
VALUES ('bq-modele-resto-sondage-habitudes', 'Restauration · Sondage : vos habitudes', 'flowin', ARRAY[]::text[],
  '[{"id":"rb-habitude-01","type":"single","label":"À quelle fréquence manges-tu au restaurant ?","options":[{"val":"a","label":"Chaque semaine"},{"val":"b","label":"Quelques fois par mois"},{"val":"c","label":"Quelques fois par an"},{"val":"d","label":"Pour les grandes occasions"}],"theme":"Fréquence"},{"id":"rb-habitude-02","type":"single","label":"Ton moment préféré pour manger dehors ?","options":[{"val":"a","label":"Déjeuner en semaine"},{"val":"b","label":"Dîner en semaine"},{"val":"c","label":"Le week-end à midi"},{"val":"d","label":"Le week-end le soir"}],"theme":"Moment"},{"id":"rb-habitude-03","type":"single","label":"Avec qui viens-tu le plus souvent ?","options":[{"val":"a","label":"En famille"},{"val":"b","label":"Entre amis"},{"val":"c","label":"En couple"},{"val":"d","label":"Avec des collègues"},{"val":"e","label":"Seul(e)"}],"theme":"Compagnie"},{"id":"rb-habitude-04","type":"single","label":"Tu réserves…","options":[{"val":"a","label":"Toujours"},{"val":"b","label":"Parfois"},{"val":"c","label":"Jamais, je tente ma chance"},{"val":"d","label":"Seulement pour les groupes"}],"theme":"Habitudes"},{"id":"rb-habitude-05","type":"single","label":"Plutôt sur place ou à emporter ?","options":[{"val":"a","label":"Sur place"},{"val":"b","label":"À emporter"},{"val":"c","label":"En livraison"},{"val":"d","label":"Un peu des trois"}],"theme":"Habitudes"},{"id":"rb-habitude-06","type":"single","label":"Terrasse ou salle ?","options":[{"val":"a","label":"Terrasse dès qu’il fait beau"},{"val":"b","label":"Salle"},{"val":"c","label":"Peu importe, c’est la table qui compte"}],"theme":"Habitudes"},{"id":"rb-habitude-07","type":"single","label":"Et vous, quel client êtes-vous ?","options":[{"val":"a","label":"L’explorateur : je teste toujours un nouveau plat"},{"val":"b","label":"Le fidèle : toujours mon plat habituel"},{"val":"c","label":"Le gourmand : je partage tout"},{"val":"d","label":"Le pressé : le service rapide avant tout"}],"theme":"Profil"},{"id":"rb-habitude-08","type":"single","label":"Quand tu choisis ton plat, tu es plutôt…","options":[{"val":"a","label":"Je lis toute la carte"},{"val":"b","label":"Je demande conseil"},{"val":"c","label":"Je prends le plat du jour"},{"val":"d","label":"J’ai choisi avant d’arriver"}],"theme":"Profil"},{"id":"rb-habitude-09","type":"single","label":"Le plus important pour une bonne soirée ?","options":[{"val":"a","label":"L’accueil"},{"val":"b","label":"L’assiette"},{"val":"c","label":"L’ambiance"},{"val":"d","label":"Le rapport qualité-prix"}],"theme":"Profil"}]'::jsonb,
  ARRAY['bonus','restaurateur','pizzeria','modele']::text[], 'valide')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.banques (id, nom, pro_id, event_ids, questions, tags, statut)
VALUES ('bq-modele-resto-sondage-idees', 'Restauration · Sondage : vos idées et votre avis', 'flowin', ARRAY[]::text[],
  '[{"id":"rb-idee-01","type":"single","label":"Quelle idée de plat aimerais-tu voir à la carte ?","options":[{"val":"a","label":"Un plat de saison"},{"val":"b","label":"Un plat du terroir local"},{"val":"c","label":"Un plat végétarien"},{"val":"d","label":"Une création surprise du chef"}],"theme":"Idées"},{"id":"rb-idee-02","type":"single","label":"Et si on organisait un atelier ?","options":[{"val":"a","label":"Un atelier pizza"},{"val":"b","label":"Un atelier cuisine du marché"},{"val":"c","label":"Une dégustation de produits locaux"},{"val":"d","label":"Rien, juste bien manger"}],"theme":"Idées"},{"id":"rb-idee-03","type":"single","label":"Quelle animation te ferait venir ?","options":[{"val":"a","label":"Une soirée musique"},{"val":"b","label":"Une soirée à thème"},{"val":"c","label":"Un menu à partager"},{"val":"d","label":"Rien de spécial"}],"theme":"Idées"},{"id":"rb-idee-04","type":"single","label":"Pour limiter le gaspillage, tu serais partant pour…","options":[{"val":"a","label":"Des portions à adapter"},{"val":"b","label":"Emporter mes restes"},{"val":"c","label":"Un plat anti-gaspi du jour"},{"val":"d","label":"Je le fais déjà"}],"theme":"Idées"},{"id":"rb-idee-05","type":"single","label":"Les produits locaux, pour toi, c’est…","options":[{"val":"a","label":"Un vrai critère de choix"},{"val":"b","label":"Un plus apprécié"},{"val":"c","label":"Je n’y fais pas attention"}],"theme":"Idées"},{"id":"rb-idee-06","type":"single","label":"Comment as-tu trouvé l’accueil aujourd’hui ?","options":[{"val":"a","label":"Au top"},{"val":"b","label":"Bien"},{"val":"c","label":"Moyen"},{"val":"d","label":"À améliorer"}],"theme":"Satisfaction"},{"id":"rb-idee-07","type":"single","label":"Recommanderais-tu notre table à un ami ?","options":[{"val":"a","label":"Sans hésiter"},{"val":"b","label":"Probablement"},{"val":"c","label":"Peut-être"},{"val":"d","label":"Pas encore"}],"theme":"Satisfaction"},{"id":"rb-idee-08","type":"single","label":"Ta prochaine visite, ce sera…","options":[{"val":"a","label":"Cette semaine"},{"val":"b","label":"Ce mois-ci"},{"val":"c","label":"Bientôt"},{"val":"d","label":"Je ne sais pas encore"}],"theme":"Satisfaction"}]'::jsonb,
  ARRAY['bonus','restaurateur','pizzeria','modele']::text[], 'valide')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.banques (id, nom, pro_id, event_ids, questions, tags, statut)
VALUES ('bq-modele-boulanger-quiz', 'Boulanger · Quiz pain, viennoiserie et pâtisserie', 'flowin', ARRAY[]::text[],
  '[{"id":"bl-quiz-01","type":"qcm","texte":"Quels sont les ingrédients de base d’un pain ?","options":["Farine, œufs, beurre et sucre","Farine, eau, sel et levure ou levain","Maïs, lait et huile","Riz, eau et vinaigre"],"bonne":1,"points":1,"explication":"Quatre ingrédients suffisent pour un pain : farine, eau, sel et levure (ou levain).","theme":"Pain","difficulte":"facile"},{"id":"bl-quiz-02","type":"qcm","texte":"Qu’est-ce qu’un levain naturel ?","options":["Un sel spécial","Un type de four","Un mélange de farine et d’eau mis à fermenter","Une farine de maïs"],"bonne":2,"points":1,"explication":"Le levain est une pâte fermentée naturellement, qui fait lever le pain et lui donne du goût.","theme":"Pain","difficulte":"facile"},{"id":"bl-quiz-03","type":"qcm","texte":"Que garantit l’appellation « pain de tradition française » ?","options":["Un pain cuit au feu de bois","Un pain fait avec de la farine bio","Un pain au seigle","Un pain sans additif, jamais surgelé"],"bonne":3,"points":1,"explication":"Cette appellation est réservée aux pains fabriqués sans additif et sans surgélation.","theme":"Pain","difficulte":"moyen"},{"id":"bl-quiz-04","type":"qcm","texte":"Que développe le pétrissage dans la pâte à pain ?","options":["La levure","Le réseau de gluten","Le sel","La couleur"],"bonne":1,"points":1,"explication":"En pétrissant, on forme le réseau de gluten qui donne de l’élasticité à la pâte.","theme":"Fabrication","difficulte":"moyen"},{"id":"bl-quiz-05","type":"qcm","texte":"Comment appelle-t-on la première fermentation de la pâte, après le pétrissage ?","options":["Le façonnage","L’enfournement","Le pointage","Le pliage"],"bonne":2,"points":1,"explication":"Le pointage est la fermentation en masse, avant de façonner les pâtons.","theme":"Fabrication","difficulte":"difficile"},{"id":"bl-quiz-06","type":"qcm","texte":"À quoi servent les coups de lame sur la pâte avant la cuisson ?","options":["À ajouter du sel","À empêcher la pâte de lever","À faire cuire plus lentement","À guider l’ouverture du pain pendant la cuisson"],"bonne":3,"points":1,"explication":"Les entailles permettent à la vapeur de s’échapper et au pain de s’ouvrir joliment.","theme":"Fabrication","difficulte":"moyen"},{"id":"bl-quiz-07","type":"qcm","texte":"À quelle température environ cuit-on une baguette ?","options":["Autour de 240 °C","Autour de 80 °C","Autour de 120 °C","Autour de 400 °C"],"bonne":0,"points":1,"explication":"Un four bien chaud, autour de 230 à 250 °C, donne une croûte dorée et croustillante.","theme":"Cuisson","difficulte":"moyen"},{"id":"bl-quiz-08","type":"qcm","texte":"Pourquoi injecte-t-on de la vapeur dans le four au début de la cuisson ?","options":["Pour saler le pain","Pour refroidir le four","Pour une croûte brillante et un pain bien gonflé","Pour laver la pâte"],"bonne":2,"points":1,"explication":"La vapeur retarde la formation de la croûte : le pain se développe avant de durcir.","theme":"Cuisson","difficulte":"moyen"},{"id":"bl-quiz-09","type":"qcm","texte":"Comment s’appelle la réaction qui dore la croûte et développe les arômes du pain ?","options":["La réaction de Curie","La réaction de Pascal","La réaction de Newton","La réaction de Maillard"],"bonne":3,"points":1,"explication":"La réaction de Maillard, entre sucres et protéines, colore et parfume la croûte.","theme":"Cuisson","difficulte":"difficile"},{"id":"bl-quiz-10","type":"qcm","texte":"Que mesure le chiffre dans « T55 » sur un sac de farine ?","options":["Le taux de minéraux (cendres)","La température de cuisson","Le temps de pétrissage","Le taux d’humidité"],"bonne":0,"points":1,"explication":"Le type de farine (T45, T55, T65…) indique son taux de cendres, donc son degré de blutage.","theme":"Farines","difficulte":"difficile"},{"id":"bl-quiz-11","type":"qcm","texte":"Qu’a-t-on conservé dans la farine d’un pain complet ?","options":["Le sucre du blé","Le son, l’enveloppe du grain","Le sel marin","Les œufs"],"bonne":1,"points":1,"explication":"La farine complète garde le son et le germe du grain.","theme":"Farines","difficulte":"moyen"},{"id":"bl-quiz-12","type":"qcm","texte":"Quel ingrédient donne son feuilletage au croissant ?","options":["L’huile de friture","Le miel","Le fromage","Le beurre"],"bonne":3,"points":1,"explication":"Le beurre est plié plusieurs fois dans la pâte : on appelle cela le tourage.","theme":"Viennoiserie","difficulte":"facile"},{"id":"bl-quiz-13","type":"qcm","texte":"Quels ingrédients riches rendent la brioche moelleuse ?","options":["Les œufs et le beurre","L’eau et le sel","Le vinaigre et le miel","Le riz et l’huile"],"bonne":0,"points":1,"explication":"La brioche est une pâte levée enrichie en œufs et en beurre.","theme":"Viennoiserie","difficulte":"facile"},{"id":"bl-quiz-14","type":"qcm","texte":"Avec quelle pâte fait-on les éclairs et les choux ?","options":["La pâte brisée","La pâte à choux","La pâte à pain","La pâte à crêpes"],"bonne":1,"points":1,"explication":"La pâte à choux gonfle à la cuisson et crée une cavité à garnir de crème.","theme":"Pâtisserie","difficulte":"facile"},{"id":"bl-quiz-15","type":"qcm","texte":"Quelle poudre est à la base de la coque d’un macaron ?","options":["La poudre de cacao","La poudre de lait","La poudre d’amande","La poudre de café"],"bonne":2,"points":1,"explication":"Poudre d’amande, sucre et blancs d’œufs : voilà la coque du macaron.","theme":"Pâtisserie","difficulte":"moyen"},{"id":"bl-quiz-16","type":"qcm","texte":"Quelle crème garnit traditionnellement un mille-feuille ?","options":["La crème pâtissière","La crème de marron","La crème de gruyère","La crème d’ail"],"bonne":0,"points":1,"explication":"Un mille-feuille alterne pâte feuilletée et crème pâtissière.","theme":"Pâtisserie","difficulte":"facile"},{"id":"bl-quiz-17","type":"qcm","texte":"De quelle région vient le kouign-amann ?","options":["L’Alsace","La Bretagne","La Provence","Le Limousin"],"bonne":1,"points":1,"explication":"Le kouign-amann, « gâteau au beurre » en breton, est une spécialité bretonne.","theme":"Régions","difficulte":"moyen"},{"id":"bl-quiz-18","type":"qcm","texte":"De quelle ville vient le canelé ?","options":["Nice","Lille","Bordeaux","Strasbourg"],"bonne":2,"points":1,"explication":"Le canelé est une petite pâtisserie bordelaise, à la croûte caramélisée.","theme":"Régions","difficulte":"moyen"},{"id":"bl-quiz-19","type":"qcm","texte":"La fougasse est un pain emblématique de quelle région ?","options":["La Normandie","La Lorraine","La Bretagne","La Provence"],"bonne":3,"points":1,"explication":"La fougasse provençale se garnit d’olives, de lardons ou d’herbes.","theme":"Régions","difficulte":"facile"},{"id":"bl-quiz-20","type":"qcm","texte":"En quelle année la baguette a-t-elle été inscrite au patrimoine culturel immatériel de l’UNESCO ?","options":["1990","2022","2005","2015"],"bonne":1,"points":1,"explication":"En 2022, l’UNESCO a reconnu le savoir-faire artisanal et la culture de la baguette de pain.","theme":"Patrimoine","difficulte":"moyen"}]'::jsonb,
  ARRAY['quiz','boulanger','modele']::text[], 'valide')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.banques (id, nom, pro_id, event_ids, questions, tags, statut)
VALUES ('bq-modele-boulanger-bonus', 'Boulanger · Sondage bonus', 'flowin', ARRAY[]::text[],
  '[{"id":"bl-bonus-01","type":"single","label":"Ton pain de cœur ?","options":[{"val":"a","label":"La baguette"},{"val":"b","label":"Le pain de campagne"},{"val":"c","label":"Le pain complet"},{"val":"d","label":"Un pain aux graines ou aux noix"}],"theme":"Goûts"},{"id":"bl-bonus-02","type":"single","label":"La viennoiserie qui te fait craquer ?","options":[{"val":"a","label":"Le croissant"},{"val":"b","label":"Le pain au chocolat"},{"val":"c","label":"La brioche"},{"val":"d","label":"Le pain aux raisins"}],"theme":"Goûts"},{"id":"bl-bonus-03","type":"single","label":"Baguette : bien cuite ou bien blonde ?","options":[{"val":"a","label":"Bien cuite, bien croustillante"},{"val":"b","label":"Blonde et moelleuse"},{"val":"c","label":"Entre les deux"},{"val":"d","label":"Je ne regarde pas !"}],"theme":"Goûts"},{"id":"bl-bonus-04","type":"single","label":"Le bout de baguette qu’on grignote en rentrant : tu l’as déjà fait ?","options":[{"val":"a","label":"Toujours"},{"val":"b","label":"Souvent"},{"val":"c","label":"Parfois"},{"val":"d","label":"Jamais, je suis raisonnable"}],"theme":"Goûts"},{"id":"bl-bonus-05","type":"single","label":"Tu passes à la boulangerie…","options":[{"val":"a","label":"Tous les jours"},{"val":"b","label":"Plusieurs fois par semaine"},{"val":"c","label":"Une fois par semaine"},{"val":"d","label":"De temps en temps"}],"theme":"Habitudes"},{"id":"bl-bonus-06","type":"single","label":"Ton moment préféré ?","options":[{"val":"a","label":"Le matin tôt"},{"val":"b","label":"À la pause de midi"},{"val":"c","label":"Au goûter"},{"val":"d","label":"Juste avant le dîner"}],"theme":"Habitudes"},{"id":"bl-bonus-07","type":"single","label":"Et vous, quel client de la boulangerie êtes-vous ?","options":[{"val":"a","label":"Le matinal : première fournée !"},{"val":"b","label":"Le gourmand : toujours une pâtisserie en plus"},{"val":"c","label":"Le pressé : sandwich et c’est parti"},{"val":"d","label":"Le fidèle : toujours la même commande"}],"theme":"Profil"},{"id":"bl-bonus-08","type":"single","label":"Quelle nouveauté aimerais-tu trouver ?","options":[{"val":"a","label":"Un pain de saison"},{"val":"b","label":"Des sandwichs maison"},{"val":"c","label":"Des pâtisseries individuelles"},{"val":"d","label":"Un atelier pour apprendre à faire son pain"}],"theme":"Idées"},{"id":"bl-bonus-09","type":"single","label":"Pour un cadeau gourmand, tu penses à…","options":[{"val":"a","label":"Un coffret de viennoiseries"},{"val":"b","label":"Un gâteau pour la famille"},{"val":"c","label":"Des biscuits"},{"val":"d","label":"Un pain-surprise"}],"theme":"Idées"},{"id":"bl-bonus-10","type":"single","label":"Comment trouves-tu l’accueil en boutique ?","options":[{"val":"a","label":"Au top"},{"val":"b","label":"Bien"},{"val":"c","label":"Moyen"},{"val":"d","label":"À améliorer"}],"theme":"Satisfaction"}]'::jsonb,
