INSERT INTO public.banques (id, nom, pro_id, event_ids, questions, tags, statut)
VALUES ('bq-modele-boucher-quiz', 'Boucher · Quiz viandes, morceaux et cuissons', 'flowin', ARRAY[]::text[],
  '[{"id":"bo-quiz-01","type":"qcm","texte":"Quel morceau de bœuf est réputé le plus tendre ?","options":["Le jarret","Le filet","La joue","Le collier"],"bonne":1,"points":1,"explication":"Le filet est un muscle peu sollicité, donc très tendre.","theme":"Morceaux","difficulte":"moyen"},{"id":"bo-quiz-02","type":"qcm","texte":"D’où vient le nom « entrecôte » ?","options":["De son lieu d’origine","Du nom d’un boucher","De sa position entre deux côtes","De sa couleur"],"bonne":2,"points":1,"explication":"L’entrecôte se coupe entre deux côtes du bœuf.","theme":"Morceaux","difficulte":"facile"},{"id":"bo-quiz-03","type":"qcm","texte":"De quelle partie de l’animal vient le gigot ?","options":["Du cou de l’agneau","Du ventre du porc","De l’aile du poulet","De la cuisse de l’agneau"],"bonne":3,"points":1,"explication":"Le gigot d’agneau est la cuisse de l’animal.","theme":"Morceaux","difficulte":"facile"},{"id":"bo-quiz-04","type":"qcm","texte":"Quelle partie du porc donne le jambon ?","options":["Le cou","La cuisse","Le museau","La queue"],"bonne":1,"points":1,"explication":"Le jambon est préparé à partir de la cuisse du porc.","theme":"Morceaux","difficulte":"facile"},{"id":"bo-quiz-05","type":"qcm","texte":"Le magret est le filet de quel animal ?","options":["De l’agneau","Du poulet","Du canard","Du lapin"],"bonne":2,"points":1,"explication":"Le magret est la poitrine charnue d’un canard engraissé.","theme":"Morceaux","difficulte":"facile"},{"id":"bo-quiz-06","type":"qcm","texte":"Que signifie « persillé » pour une viande ?","options":["Elle est recouverte de persil","Elle est salée","Elle est congelée","Elle contient de fines veinules de gras dans le muscle"],"bonne":3,"points":1,"explication":"Ce gras fond à la cuisson et rend la viande plus savoureuse.","theme":"Morceaux","difficulte":"moyen"},{"id":"bo-quiz-07","type":"qcm","texte":"Pourquoi laisse-t-on reposer une viande après la cuisson ?","options":["Pour que les jus se répartissent dans la chair","Pour la refroidir complètement","Pour qu’elle sèche","Pour la saler"],"bonne":0,"points":1,"explication":"Le repos évite que les jus ne s’échappent à la découpe.","theme":"Savoir-faire","difficulte":"moyen"},{"id":"bo-quiz-08","type":"qcm","texte":"En quoi consiste la maturation d’une viande ?","options":["La congeler pendant des mois","La faire sécher au soleil","La laisser vieillir au froid pour la rendre plus tendre et plus parfumée","La plonger dans l’huile"],"bonne":2,"points":1,"explication":"La maturation, au froid et sous contrôle, attendrit et affine le goût.","theme":"Savoir-faire","difficulte":"difficile"},{"id":"bo-quiz-09","type":"qcm","texte":"Que signifie « barder » un rôti ?","options":["Le piquer de clous","Le couper en deux","Le tremper dans du lait","L’entourer d’une fine tranche de gras"],"bonne":3,"points":1,"explication":"La barde protège la viande du dessèchement pendant la cuisson.","theme":"Savoir-faire","difficulte":"moyen"},{"id":"bo-quiz-10","type":"qcm","texte":"Comment s’appelle la tige d’acier qui sert au boucher à entretenir le fil de ses couteaux ?","options":["Le fusil","Le hachoir","La louche","La spatule"],"bonne":0,"points":1,"explication":"Le fusil redresse le fil de la lame entre deux affûtages.","theme":"Savoir-faire","difficulte":"facile"},{"id":"bo-quiz-11","type":"qcm","texte":"Pourquoi cuit-on plus à cœur un steak haché qu’un steak entier ?","options":["Parce qu’il est plus gras","Parce que le hachage répartit la surface de la viande dans toute la préparation","Parce qu’il est plus froid","Pour qu’il soit plus rouge"],"bonne":1,"points":1,"explication":"Une viande hachée doit être bien cuite à cœur par précaution d’hygiène.","theme":"Cuisson","difficulte":"moyen"},{"id":"bo-quiz-12","type":"qcm","texte":"Quel plat mijote du bœuf avec carottes, poireaux et navets dans un bouillon ?","options":["La choucroute","Le cassoulet","La paella","Le pot-au-feu"],"bonne":3,"points":1,"explication":"Le pot-au-feu est un grand classique de la cuisine française, servi avec le bouillon.","theme":"Cuisson","difficulte":"facile"},{"id":"bo-quiz-13","type":"qcm","texte":"Quelle viande est la base de la blanquette ?","options":["Le veau","Le canard","Le sanglier","Le lapin"],"bonne":0,"points":1,"explication":"La blanquette est un plat mijoté de veau, en sauce blanche.","theme":"Cuisson","difficulte":"facile"},{"id":"bo-quiz-14","type":"qcm","texte":"Quel plat mijote du bœuf avec du vin rouge, des lardons et des champignons ?","options":["La blanquette de veau","Le bœuf bourguignon","Le couscous","Le pot-au-feu de poisson"],"bonne":1,"points":1,"explication":"Le bœuf bourguignon vient de Bourgogne, terre de vins.","theme":"Cuisson","difficulte":"facile"},{"id":"bo-quiz-15","type":"qcm","texte":"Quel ingrédient donne sa couleur sombre au boudin noir ?","options":["Le chocolat","L’encre de seiche","Le sang","Le café"],"bonne":2,"points":1,"explication":"Le boudin noir est préparé avec du sang de porc, du gras et des oignons.","theme":"Charcuterie","difficulte":"facile"},{"id":"bo-quiz-16","type":"qcm","texte":"De quoi est principalement fait un saucisson sec ?","options":["De viande de porc hachée et de gras","De poisson fumé","De farine de blé","De fromage"],"bonne":0,"points":1,"explication":"Le saucisson sec est séché plusieurs semaines après avoir été assaisonné.","theme":"Charcuterie","difficulte":"facile"},{"id":"bo-quiz-17","type":"qcm","texte":"Que signifie le logo « Viande Bovine Française » ?","options":["L’animal a été congelé en France","L’animal est né, élevé et abattu en France","La viande est toujours bio","La viande est toujours du Label Rouge"],"bonne":1,"points":1,"explication":"Ce logo garantit l’origine française de la viande de bœuf.","theme":"Labels","difficulte":"moyen"},{"id":"bo-quiz-18","type":"qcm","texte":"De quelle région vient la race bovine charolaise ?","options":["La Bretagne","L’Alsace","La Bourgogne (le Charolais)","La Corse"],"bonne":2,"points":1,"explication":"La charolaise est une race à viande originaire du Charolais, en Bourgogne.","theme":"Races et terroirs","difficulte":"moyen"},{"id":"bo-quiz-19","type":"qcm","texte":"Dans quel département est élevé l’agneau de Sisteron (IGP) ?","options":["Le Nord","La Manche","Le Finistère","Les Alpes-de-Haute-Provence"],"bonne":3,"points":1,"explication":"L’agneau de Sisteron est une indication géographique protégée de Haute-Provence.","theme":"Races et terroirs","difficulte":"moyen"},{"id":"bo-quiz-20","type":"qcm","texte":"Quelle viande bénéficie d’une AOP en Camargue ?","options":["Le sanglier","Le taureau","Le cheval","Le canard"],"bonne":1,"points":1,"explication":"Le taureau de Camargue est une appellation d’origine protégée.","theme":"Races et terroirs","difficulte":"difficile"}]'::jsonb,
  ARRAY['quiz','boucher','modele']::text[], 'valide')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.banques (id, nom, pro_id, event_ids, questions, tags, statut)
VALUES ('bq-modele-boucher-bonus', 'Boucher · Sondage bonus', 'flowin', ARRAY[]::text[],
  '[{"id":"bo-bonus-01","type":"single","label":"La viande de ta table du dimanche ?","options":[{"val":"a","label":"Le rôti"},{"val":"b","label":"Le poulet"},{"val":"c","label":"Les grillades"},{"val":"d","label":"Un plat mijoté"}],"theme":"Goûts"},{"id":"bo-bonus-02","type":"single","label":"Ta cuisson de viande rouge ?","options":[{"val":"a","label":"Bleue"},{"val":"b","label":"Saignante"},{"val":"c","label":"À point"},{"val":"d","label":"Bien cuite"}],"theme":"Goûts"},{"id":"bo-bonus-03","type":"single","label":"Au barbecue, tu prends en premier…","options":[{"val":"a","label":"Les brochettes"},{"val":"b","label":"Les saucisses"},{"val":"c","label":"Une côte"},{"val":"d","label":"Le poulet mariné"}],"theme":"Goûts"},{"id":"bo-bonus-04","type":"single","label":"Une marinade, plutôt…","options":[{"val":"a","label":"Aux herbes"},{"val":"b","label":"Aux épices"},{"val":"c","label":"Au citron"},{"val":"d","label":"Nature, rien de plus"}],"theme":"Goûts"},{"id":"bo-bonus-05","type":"single","label":"Tu viens chez ton boucher…","options":[{"val":"a","label":"Chaque semaine"},{"val":"b","label":"Quelques fois par mois"},{"val":"c","label":"Pour les grandes occasions"},{"val":"d","label":"Pour le barbecue"}],"theme":"Habitudes"},{"id":"bo-bonus-06","type":"single","label":"Pour choisir ta viande, tu comptes sur…","options":[{"val":"a","label":"Le conseil du boucher"},{"val":"b","label":"Ma recette du jour"},{"val":"c","label":"Le prix"},{"val":"d","label":"L’origine"}],"theme":"Habitudes"},{"id":"bo-bonus-07","type":"single","label":"Et vous, quel client de la boucherie êtes-vous ?","options":[{"val":"a","label":"Le cuisinier : je viens avec ma recette"},{"val":"b","label":"Le curieux : je demande un morceau que je ne connais pas"},{"val":"c","label":"Le grillardin : barbecue en vue"},{"val":"d","label":"Le pressé : prêt à cuire, merci"}],"theme":"Profil"},{"id":"bo-bonus-08","type":"single","label":"Qu’aimerais-tu trouver en plus ?","options":[{"val":"a","label":"Des plats cuisinés maison"},{"val":"b","label":"Des marinades prêtes à cuire"},{"val":"c","label":"Des conseils de cuisson"},{"val":"d","label":"Des coffrets pour le barbecue"}],"theme":"Idées"},{"id":"bo-bonus-09","type":"single","label":"L’origine de la viande, pour toi…","options":[{"val":"a","label":"C’est essentiel"},{"val":"b","label":"C’est un plus"},{"val":"c","label":"Je n’y prête pas attention"}],"theme":"Idées"},{"id":"bo-bonus-10","type":"single","label":"Comment trouves-tu les conseils du boucher ?","options":[{"val":"a","label":"Précieux"},{"val":"b","label":"Utiles"},{"val":"c","label":"Moyens"},{"val":"d","label":"À améliorer"}],"theme":"Satisfaction"}]'::jsonb,
  ARRAY['bonus','boucher','modele']::text[], 'valide')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.banques (id, nom, pro_id, event_ids, questions, tags, statut)
VALUES ('bq-modele-libraire-quiz', 'Libraire · Quiz littérature et livres', 'flowin', ARRAY[]::text[],
  '[{"id":"lb-quiz-01","type":"qcm","texte":"Qui a écrit « Les Misérables » ?","options":["Émile Zola","Victor Hugo","Honoré de Balzac","Gustave Flaubert"],"bonne":1,"points":1,"explication":"Victor Hugo a publié « Les Misérables » en 1862.","theme":"Classiques","difficulte":"facile"},{"id":"lb-quiz-02","type":"qcm","texte":"Qui a écrit « Le Petit Prince » ?","options":["Jules Verne","Albert Camus","Antoine de Saint-Exupéry","Marcel Pagnol"],"bonne":2,"points":1,"explication":"Saint-Exupéry est aussi aviateur ; son conte est l’un des livres les plus traduits au monde.","theme":"Classiques","difficulte":"facile"},{"id":"lb-quiz-03","type":"qcm","texte":"Dans quel pays se déroule « Don Quichotte » ?","options":["En Italie","Au Portugal","En France","En Espagne"],"bonne":3,"points":1,"explication":"Le roman de Cervantès se déroule en Espagne, dans la Manche.","theme":"Classiques","difficulte":"facile"},{"id":"lb-quiz-04","type":"qcm","texte":"Qui a écrit « L’Étranger » ?","options":["Jean-Paul Sartre","Albert Camus","Marguerite Duras","André Gide"],"bonne":1,"points":1,"explication":"Albert Camus a publié « L’Étranger » en 1942.","theme":"Classiques","difficulte":"moyen"},{"id":"lb-quiz-05","type":"qcm","texte":"Qui est l’auteur de « Madame Bovary » ?","options":["Stendhal","Alexandre Dumas","Gustave Flaubert","Guy de Maupassant"],"bonne":2,"points":1,"explication":"Le roman de Flaubert paraît en 1857.","theme":"Classiques","difficulte":"moyen"},{"id":"lb-quiz-06","type":"qcm","texte":"Qui a écrit « Le Comte de Monte-Cristo » ?","options":["Victor Hugo","Honoré de Balzac","Jules Verne","Alexandre Dumas"],"bonne":3,"points":1,"explication":"Alexandre Dumas est aussi l’auteur des « Trois Mousquetaires ».","theme":"Classiques","difficulte":"facile"},{"id":"lb-quiz-07","type":"qcm","texte":"Comment s’appelle le capitaine du Nautilus dans « Vingt mille lieues sous les mers » ?","options":["Nemo","Achab","Haddock","Crochet"],"bonne":0,"points":1,"explication":"Le capitaine Nemo est le personnage énigmatique du roman de Jules Verne.","theme":"Classiques","difficulte":"moyen"},{"id":"lb-quiz-08","type":"qcm","texte":"Dans « Les Trois Mousquetaires », comment s’appelle le jeune Gascon ?","options":["Rodrigue","Roland","D’Artagnan","Figaro"],"bonne":2,"points":1,"explication":"D’Artagnan rejoint Athos, Porthos et Aramis.","theme":"Classiques","difficulte":"moyen"},{"id":"lb-quiz-09","type":"qcm","texte":"Qui a écrit « À la recherche du temps perdu » ?","options":["André Malraux","Louis Aragon","Colette","Marcel Proust"],"bonne":3,"points":1,"explication":"Cette œuvre en sept volumes est l’un des sommets de la littérature française.","theme":"Classiques","difficulte":"difficile"},{"id":"lb-quiz-10","type":"qcm","texte":"Qui a écrit les « Fables » où l’on trouve « La Cigale et la Fourmi » ?","options":["Jean de La Fontaine","Charles Perrault","Molière","Victor Hugo"],"bonne":0,"points":1,"explication":"La Fontaine a mis en vers des fables célèbres au XVIIe siècle.","theme":"Classiques","difficulte":"facile"},{"id":"lb-quiz-11","type":"qcm","texte":"Qui a écrit « Germinal » ?","options":["Victor Hugo","Émile Zola","Guy de Maupassant","Alphonse Daudet"],"bonne":1,"points":1,"explication":"Zola y raconte la vie des mineurs du Nord.","theme":"Classiques","difficulte":"moyen"},{"id":"lb-quiz-12","type":"qcm","texte":"Qui a écrit « Les Fleurs du mal » ?","options":["Arthur Rimbaud","Paul Verlaine","Alfred de Musset","Charles Baudelaire"],"bonne":3,"points":1,"explication":"Baudelaire publie « Les Fleurs du mal » en 1857.","theme":"Poésie et théâtre","difficulte":"moyen"},{"id":"lb-quiz-13","type":"qcm","texte":"Qui a écrit la pièce « Cyrano de Bergerac » ?","options":["Edmond Rostand","Molière","Jean Racine","Victor Hugo"],"bonne":0,"points":1,"explication":"Cyrano, son grand nez et son panache sont nés sous la plume d’Edmond Rostand.","theme":"Poésie et théâtre","difficulte":"moyen"},{"id":"lb-quiz-14","type":"qcm","texte":"Combien de syllabes compte un alexandrin ?","options":["Huit","Douze","Dix","Quatorze"],"bonne":1,"points":1,"explication":"L’alexandrin est le vers de douze syllabes.","theme":"Poésie et théâtre","difficulte":"moyen"},{"id":"lb-quiz-15","type":"qcm","texte":"Que signifie le sigle ISBN ?","options":["Index des succès de bibliothèque nationale","Imprimé sur beau noir","Numéro international normalisé du livre","Inventaire standard des beaux numéros"],"bonne":2,"points":1,"explication":"L’ISBN (International Standard Book Number) identifie chaque édition d’un livre.","theme":"Vocabulaire du livre","difficulte":"moyen"},{"id":"lb-quiz-16","type":"qcm","texte":"Qu’appelle-t-on l’« incipit » d’un roman ?","options":["Ses premiers mots ou ses premières phrases","Sa dernière page","Sa couverture","Son résumé au dos"],"bonne":0,"points":1,"explication":"L’incipit est le début du texte : il doit donner envie de poursuivre.","theme":"Vocabulaire du livre","difficulte":"moyen"},{"id":"lb-quiz-17","type":"qcm","texte":"Quel inventeur est associé à l’imprimerie à caractères mobiles en Europe, au XVe siècle ?","options":["Léonard de Vinci","Johannes Gutenberg","Christophe Colomb","Galilée"],"bonne":1,"points":1,"explication":"Gutenberg a mis au point l’imprimerie vers 1450 à Mayence.","theme":"Vocabulaire du livre","difficulte":"facile"},{"id":"lb-quiz-18","type":"qcm","texte":"Quel prix littéraire français porte le nom de deux frères écrivains ?","options":["Le prix Nobel","Le prix Pulitzer","Le prix Goncourt","Le prix Fémina"],"bonne":2,"points":1,"explication":"Le prix Goncourt honore la mémoire d’Edmond et Jules de Goncourt ; il est remis chaque automne.","theme":"Vocabulaire du livre","difficulte":"difficile"},{"id":"lb-quiz-19","type":"qcm","texte":"Quel auteur a écrit « La Gloire de mon père » ?","options":["Jean Giono","Alphonse Daudet","Frédéric Mistral","Marcel Pagnol"],"bonne":3,"points":1,"explication":"Marcel Pagnol raconte ses souvenirs d’enfance en Provence.","theme":"Auteurs du Sud","difficulte":"moyen"},{"id":"lb-quiz-20","type":"qcm","texte":"Quel auteur de « Le Hussard sur le toit » est né à Manosque ?","options":["Marcel Pagnol","Jean Giono","Albert Camus","Colette"],"bonne":1,"points":1,"explication":"Jean Giono est l’un des grands écrivains de la Provence.","theme":"Auteurs du Sud","difficulte":"difficile"}]'::jsonb,
  ARRAY['quiz','libraire','modele']::text[], 'valide')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.banques (id, nom, pro_id, event_ids, questions, tags, statut)
VALUES ('bq-modele-libraire-bonus', 'Libraire · Sondage bonus', 'flowin', ARRAY[]::text[],
  '[{"id":"lb-bonus-01","type":"single","label":"Ton genre préféré ?","options":[{"val":"a","label":"Roman"},{"val":"b","label":"Policier"},{"val":"c","label":"BD et manga"},{"val":"d","label":"Documentaire ou histoire"},{"val":"e","label":"Jeunesse"}],"theme":"Goûts"},{"id":"lb-bonus-02","type":"single","label":"Le livre idéal pour les vacances ?","options":[{"val":"a","label":"Un gros roman"},{"val":"b","label":"Un polar qui se dévore"},{"val":"c","label":"Un guide pour explorer"},{"val":"d","label":"Une BD légère"}],"theme":"Goûts"},{"id":"lb-bonus-03","type":"single","label":"Tu lis surtout…","options":[{"val":"a","label":"Sur papier"},{"val":"b","label":"En poche"},{"val":"c","label":"Sur liseuse"},{"val":"d","label":"En livre audio"}],"theme":"Habitudes"},{"id":"lb-bonus-04","type":"single","label":"Tu lis plutôt…","options":[{"val":"a","label":"Le soir au lit"},{"val":"b","label":"Dans les transports"},{"val":"c","label":"En vacances"},{"val":"d","label":"Quand je peux !"}],"theme":"Habitudes"},{"id":"lb-bonus-05","type":"single","label":"Combien de livres lis-tu environ par an ?","options":[{"val":"a","label":"Un à trois"},{"val":"b","label":"Quatre à dix"},{"val":"c","label":"Plus de dix"},{"val":"d","label":"Je n’ai pas compté"}],"theme":"Habitudes"},{"id":"lb-bonus-06","type":"single","label":"Et vous, quel lecteur êtes-vous ?","options":[{"val":"a","label":"Le fidèle : je relis mes classiques"},{"val":"b","label":"Le curieux : je tente un auteur inconnu"},{"val":"c","label":"Le boulimique : un livre à peine fini, un autre commencé"},{"val":"d","label":"Le conseillé : je fais confiance à mon libraire"}],"theme":"Profil"},{"id":"lb-bonus-07","type":"single","label":"Pour choisir ton prochain livre, tu te fies…","options":[{"val":"a","label":"Au conseil du libraire"},{"val":"b","label":"À la couverture"},{"val":"c","label":"Au bouche-à-oreille"},{"val":"d","label":"Aux prix littéraires"}],"theme":"Profil"},{"id":"lb-bonus-08","type":"single","label":"Quelle animation te plairait en librairie ?","options":[{"val":"a","label":"Une rencontre avec un auteur"},{"val":"b","label":"Un club de lecture"},{"val":"c","label":"Un atelier d’écriture"},{"val":"d","label":"Une dédicace"}],"theme":"Idées"},{"id":"lb-bonus-09","type":"single","label":"Pour offrir, tu penses plutôt à…","options":[{"val":"a","label":"Un roman"},{"val":"b","label":"Une BD"},{"val":"c","label":"Un livre de cuisine"},{"val":"d","label":"Un livre pour enfants"}],"theme":"Idées"},{"id":"lb-bonus-10","type":"single","label":"Comment trouves-tu les conseils de lecture en boutique ?","options":[{"val":"a","label":"Excellents"},{"val":"b","label":"Utiles"},{"val":"c","label":"Moyens"},{"val":"d","label":"À améliorer"}],"theme":"Satisfaction"}]'::jsonb,
  ARRAY['bonus','libraire','modele']::text[], 'valide')
ON CONFLICT (id) DO NOTHING;

-- Contrôle après exécution : 16 banques attendues.
SELECT id, nom, jsonb_array_length(questions) AS nb_questions, tags FROM public.banques WHERE id LIKE 'bq-modele-%' ORDER BY id;
